package com.sumedha.commerce.product.mapper; import com.sumedha.commerce.product.dto.response.CategoryResponse; import com.sumedha.commerce.product.entity.Category; public final class CategoryMapper {private CategoryMapper(){} public static CategoryResponse toResponse(Category c){return new CategoryResponse(c.getId(),c.getName(),c.getSlug(),c.getDescription(),c.getParentCategoryId(),c.isActive());}}
